   Optimizations vs. the original kernel:
   - All sweeps over the data matrix use row-major order (i outer, j inner)
     to get unit-stride accesses in the innermost loop.
   - The reciprocal of float_n and sqrt(float_n) are computed once and
     reused (strength reduction).
   - Centering (subtracting the mean) is fused with variance accumulation
     to avoid a separate pass over the data.
   - Normalization uses a per-column scale factor
         scale_j = 1 / (sqrt(float_n) * stddev[j])
     so the inner loop does only multiplies (no divides or extra sqrts).
   - The correlation matrix is computed as a sequence of outer products
     over rows of the normalized data:
         corr += data_row^T * data_row   (upper triangle only),
     which accesses 'data' row-major and 'corr' row-major.
 */
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Hoist loop-invariant scalar computations.  These values are reused
     many times inside the SCoP region. */
  const DATA_TYPE inv_float_n      = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE sqrt_float_n     = SQRT_FUN(float_n);
  const DATA_TYPE inv_sqrt_float_n = SCALAR_VAL(1.0) / sqrt_float_n;

#pragma scop
  /* 1. Compute column means.
     mean[j] = (1/float_n) * sum_i data[i][j]

     Reordered to traverse 'data' row-major:
       - initialize mean[j] to 0
       - accumulate over rows (i outer, j inner) for better locality
   */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean[j] += data[i][j];

  for (j = 0; j < _PB_M; j++)
    mean[j] *= inv_float_n;


  /* 2. Compute column standard deviations while centering the data.

       After this phase:
         - data[i][j] holds (orig_data[i][j] - mean[j])
         - stddev[j] holds sum_i (orig_data[i][j] - mean[j])^2

       Then we convert sums to standard deviations and apply the
       epsilon guard as in the original code.
   */
  for (j = 0; j < _PB_M; j++)
    stddev[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        DATA_TYPE diff = data[i][j] - mean[j];
        data[i][j] = diff;
        stddev[j] += diff * diff;
      }

  for (j = 0; j < _PB_M; j++)
    {
      stddev[j] *= inv_float_n;       /* variance */
      stddev[j] = SQRT_FUN(stddev[j]);/* standard deviation */
      /* Handle near-zero std. dev. to avoid division by ~0 later. */
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }


  /* 3. Normalize the data in-place.

       Original code:
         data[i][j] = (orig - mean[j]) / (sqrt(float_n) * stddev[j])

       Here:
         - data[i][j] already holds (orig - mean[j]).
         - We multiply by per-column scale:
             scale_j = 1 / (sqrt(float_n) * stddev[j])
         so the inner loop is a single FMA-friendly multiply.
   */
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE stddev_j = stddev[j];
      DATA_TYPE scale    = inv_sqrt_float_n / stddev_j;

      for (i = 0; i < _PB_N; i++)
        data[i][j] *= scale;
    }


  /* 4. Compute the m * m correlation matrix.

       After normalization, each column of 'data' has zero mean and
       unit variance (up to the epsilon guard), so:

         corr[p][q] = sum_k data[k][p] * data[k][q]

       We compute only the upper triangle using a row-major friendly
       scheme and then mirror it to the lower triangle. The diagonal
       is set explicitly to 1.0, exactly as in the original code.
   */

  /* 4a. Initialize upper triangle (including diagonal) to 0.0. */
  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      corr[i][j] = SCALAR_VAL(0.0);

  /* 4b. Accumulate outer products of normalized rows:
         for each sample k, update corr with data[k]^T * data[k]
         (upper triangle only).
     Access pattern:
       - data[k][*] is traversed row-major (contiguous in j)
       - corr[i][*] is also traversed with j as the innermost index
  */
  for (k = 0; k < _PB_N; k++)
    {
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE x = data[k][i];
          for (j = i; j < _PB_M; j++)
            corr[i][j] += x * data[k][j];
        }
    }

  /* 4c. Enforce symmetry and set the diagonal exactly to 1.0. */
  for (i = 0; i < _PB_M; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i + 1; j < _PB_M; j++)
        corr[j][i] = corr[i][j];
    }
#pragma endscop

}


