static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;
  /* Extra loop indices for tiled correlation computation. */
  int jj, kk;

  /* Small epsilon to avoid division by very small stddev values. */
  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Hoisted scalar invariants used throughout the kernel. */
  const DATA_TYPE inv_float_n   = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE sqrt_float_n  = SQRT_FUN(float_n);

  /* Tile size for the correlation matrix along both feature dimensions.
     32 keeps a corr tile (32x32 doubles = 8 KB) comfortably in L1 cache. */
  const int tile_m = 32;

#pragma scop
  /* --------------------------------------------------------------------
   * 1. Compute column means:
   *      mean[j] = (1/float_n) * sum_i data[i][j]
   *
   * Reordered loops to traverse data row-major (i outer, j inner), which
   * gives unit-stride accesses in the inner loop and improves cache
   * locality and vectorization.
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_M; ++j)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; ++i)
    for (j = 0; j < _PB_M; ++j)
      mean[j] += data[i][j];

  for (j = 0; j < _PB_M; ++j)
    mean[j] *= inv_float_n;

  /* --------------------------------------------------------------------
   * 2. Compute column standard deviations:
   *
   *    stddev[j] = sqrt( (1/float_n) * sum_i (data[i][j] - mean[j])^2 )
   *    stddev[j] = (stddev[j] <= eps) ? 1.0 : stddev[j]
   *
   * This uses the same two-pass formula as the original code: first
   * compute the mean, then the sum of squared deviations. The only
   * difference is the loop order (i outer, j inner) to respect the
   * row-major layout of data.
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_M; ++j)
    stddev[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; ++i)
    for (j = 0; j < _PB_M; ++j)
    {
      DATA_TYPE diff = data[i][j] - mean[j];
      stddev[j] += diff * diff;
    }

  for (j = 0; j < _PB_M; ++j)
  {
    /* Divide by N and take the square root. */
    stddev[j] = SQRT_FUN(stddev[j] * inv_float_n);

    /* Clamp very small stddev values to 1.0, as in the original code,
       to avoid division by (near-)zero during normalization. */
    stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
  }

  /* --------------------------------------------------------------------
   * 3. Center and normalize the data in-place:
   *
   *    data[i][j] <- (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
   *
   * We rewrite this as:
   *
   *    scale_j = 1 / (sqrt(float_n) * stddev[j])
   *    data[i][j] <- (data[i][j] - mean[j]) * scale_j
   *
   * which preserves semantics but replaces a per-element division by a
   * multiplication, and hoists sqrt(float_n) out of the loops.
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_M; ++j)
  {
    /* Per-column normalization factor. */
    DATA_TYPE scale = SCALAR_VAL(1.0) / (sqrt_float_n * stddev[j]);

    for (i = 0; i < _PB_N; ++i)
    {
      DATA_TYPE centered = data[i][j] - mean[j];
      data[i][j] = centered * scale;
    }
  }

  /* --------------------------------------------------------------------
   * 4. Compute the M x M correlation matrix.
   *
   * After normalization, each column j of data has zero mean and unit
   * variance (up to the eps clamp). The Pearson correlation between
   * variables p and q is therefore:
   *
   *    corr[p][q] = sum_i data[i][p] * data[i][q]
   *
   * We compute this as a symmetric rank-k update:
   *
   *    C := data^T * data
   *
   * but only form the upper triangle and then mirror it to the lower
   * triangle. The computation is tiled along the column dimensions to
   * improve cache locality on corr.
   * ------------------------------------------------------------------ */

  /* 4a. Initialize upper triangle (including diagonal) to zero.
         The diagonal will be set exactly to 1.0 afterwards. */
  for (i = 0; i < _PB_M; ++i)
    for (j = i; j < _PB_M; ++j)
      corr[i][j] = SCALAR_VAL(0.0);

  /* 4b. Tiled symmetric rank-k update on the upper triangle.
         Outer loops jj, kk iterate over tiles of the (column, column)
         space. For each (jj, kk) tile, we accumulate contributions from
         all rows i into corr[j][k] for j in [jj, j_max) and
         k in [max(j, kk), k_max). The condition k_start = max(j, kk)
         ensures we only touch the upper triangle (j <= k).
   */
  for (jj = 0; jj < _PB_M; jj += tile_m)
  {
    int j_max = jj + tile_m;
    if (j_max > _PB_M)
      j_max = _PB_M;

    /* kk starts from jj so that we only visit tiles on or above the
       main diagonal (upper-triangular tiles). */
    for (kk = jj; kk < _PB_M; kk += tile_m)
    {
      int k_max = kk + tile_m;
      if (k_max > _PB_M)
        k_max = _PB_M;

      for (i = 0; i < _PB_N; ++i)
      {
        for (j = jj; j < j_max; ++j)
        {
          DATA_TYPE data_ij = data[i][j];

          /* Ensure we stay in the upper triangle: k >= j and k >= kk. */
          int k_start = (j > kk) ? j : kk;

          for (k = k_start; k < k_max; ++k)
          {
            corr[j][k] += data_ij * data[i][k];
          }
        }
      }
    }
  }

  /* 4c. Enforce symmetry and set the diagonal exactly to 1.0,
         matching the behavior of the original kernel. */
  for (i = 0; i < _PB_M; ++i)
  {
    corr[i][i] = SCALAR_VAL(1.0);
    for (j = i + 1; j < _PB_M; ++j)
      corr[j][i] = corr[i][j];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
