  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Hoisted invariant scalars. */
  const DATA_TYPE inv_n      = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE sqrt_n     = SQRT_FUN(float_n);
  const DATA_TYPE inv_sqrt_n = SCALAR_VAL(1.0) / sqrt_n;

#pragma scop
  /* 1. Compute column means:
   *      mean[j] = (1 / float_n) * sum_{i=0..N-1} data_raw[i][j]
   *
   * In our transposed storage, the raw value at (i,j) is data[j][i].
   * We accumulate sums over contiguous memory in the inner loop.
   */
  for (j = 0; j < _PB_M; j++)
  {
    DATA_TYPE sum = SCALAR_VAL(0.0);
    DATA_TYPE * __restrict col = data[j];

    for (i = 0; i < _PB_N; i++)
      sum += col[i];

    mean[j] = sum * inv_n;
  }


  /* 2. Compute column standard deviations:
   *
   *    stddev[j] = sqrt( (1 / float_n) * sum_i (data_raw[i][j] - mean[j])^2 )
   *    stddev[j] = (stddev[j] <= eps ? 1.0 : stddev[j])
   *
   * We use the raw data (still uncentered) in `data[j][i]`.
   */
  for (j = 0; j < _PB_M; j++)
  {
    DATA_TYPE var = SCALAR_VAL(0.0);
    const DATA_TYPE mean_j = mean[j];
    DATA_TYPE * __restrict col = data[j];

    for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE diff = col[i] - mean_j;
      var += diff * diff;
    }

    var *= inv_n;
    DATA_TYPE std = SQRT_FUN(var);
    std = (std <= eps) ? SCALAR_VAL(1.0) : std;
    stddev[j] = std;
  }


  /* 3. Center and normalize the column vectors in-place:
   *
   *    data[i][j] <- (data_raw[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
   *
   * Rewritten using a precomputed scale factor per column:
   *
   *    scale_j = inv_sqrt_n / stddev[j];
   *    data[i][j] <- (data_raw[i][j] - mean[j]) * scale_j;
   *
   * This is algebraically identical but avoids an expensive division
   * and call to SQRT_FUN(float_n) in the inner loop.
   */
  for (j = 0; j < _PB_M; j++)
  {
    const DATA_TYPE mean_j = mean[j];
    const DATA_TYPE scale_j = inv_sqrt_n / stddev[j];
    DATA_TYPE * __restrict col = data[j];

    for (i = 0; i < _PB_N; i++)
      col[i] = (col[i] - mean_j) * scale_j;
