  for (i = 0; i < _PB_M; i++)
    corr[i][i] = SCALAR_VAL(1.0);

  /* Off-diagonal elements; exploit symmetry corr[i][j] == corr[j][i]. */
  for (i = 0; i < _PB_M - 1; i++)
  {
    DATA_TYPE * __restrict col_i = data[i];

    for (j = i + 1; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      DATA_TYPE * __restrict col_j = data[j];

      for (k = 0; k < _PB_N; k++)
        sum += col_i[k] * col_j[k];

      corr[i][j] = sum;
      corr[j][i] = sum;
    }
  }
#pragma endscop

